import type { PluginOptions } from '@docusaurus/plugin-content-docs'

type SidebarItemsGenerator = PluginOptions['sidebarItemsGenerator']
type SidebarItem = Awaited<ReturnType<SidebarItemsGenerator>>[number]

/** Where `yarn gen-api-docs` writes the REST API endpoint pages */
const restApiReferenceDir = '03-multi-user/03-guides/05-rest-api/reference'

/**
 * The autogenerated sidebar would list the REST API endpoint pages in one flat
 * category. Replace it with the sidebar generated from the OpenAPI document,
 * which groups the endpoints by tag.
 */
const sidebarItemsGenerator: SidebarItemsGenerator = async ({
  defaultSidebarItemsGenerator,
  ...args
}) => {
  const items = await defaultSidebarItemsGenerator(args)

  // Generated by `yarn gen-api-docs`, which `yarn start` and `yarn build` run
  // first. It's imported here rather than at the top of the file because
  // `gen-api-docs` loads the Docusaurus config before writing it.
  const { default: restApiSidebar } = (await import(
    `./docs/${restApiReferenceDir}/sidebar`
  )) as { default: SidebarItem[] }

  // The generated sidebar's doc IDs keep the directories' number prefixes,
  // which Docusaurus removes from the real doc IDs
  const referenceDocIds = new Map<string, string>()
  for (const doc of args.docs) {
    if (doc.sourceDirName === restApiReferenceDir) {
      referenceDocIds.set(doc.id.split('/').at(-1) ?? doc.id, doc.id)
    }
  }
  const fixDocId = (id: string) => {
    const docId = referenceDocIds.get(id.split('/').at(-1) ?? id)
    if (!docId) {
      throw new Error(`REST API reference doc "${id}" not found`)
    }
    return docId
  }
  const fixDocIds = (item: SidebarItem): SidebarItem => {
    if (item.type === 'doc') {
      return { ...item, id: fixDocId(item.id) }
    }
    if (item.type === 'category') {
      return {
        ...item,
        link:
          item.link?.type === 'doc'
            ? { ...item.link, id: fixDocId(item.link.id) }
            : item.link,
        items: item.items.map((child) => fixDocIds(child)),
      }
    }
    return item
  }

  const replaceReference = (item: SidebarItem): SidebarItem => {
    if (item.type !== 'category') {
      return item
    }
    const isReference = item.items.some(
      (child) =>
        child.type === 'doc' &&
        referenceDocIds.get(child.id.split('/').at(-1) ?? child.id) ===
          child.id,
    )
    if (isReference) {
      return {
        ...item,
        label: 'Endpoints',
        collapsed: false,
        items: restApiSidebar.map((child) => fixDocIds(child)),
      }
    }
    return {
      ...item,
      items: item.items.map((child) => replaceReference(child)),
    }
  }

  return items.map((item) => replaceReference(item))
}

export default sidebarItemsGenerator
